"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["91332"],{86720(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.publicacoes.ato_normativo.classe_congelamento_divergente","status":422,"titulo":"A classe de congelamento do ato que retifica deve coincidir com a do ato retificado"},"descricao":{"codigo":"uniplus.publicacoes.ato_normativo.classe_congelamento_divergente","requisitos":["UNI-REQ-0156","UNI-REQ-0157"],"oQueAconteceu":["A **classe de congelamento** do ato que retifica n\xe3o coincide com a do\\nato retificado \u2014 um ato n\xe3o congelante retificando um congelante, ou o\\ninverso.","O que decide se um ato congela a configura\xe7\xe3o \xe9 a classe de\\ncongelamento \u2014 o `congelaConfiguracao` que foi copiado por valor do tipo\\nde ato no instante em que cada um dos dois foi registrado \u2014, n\xe3o o r\xf3tulo\\ndo tipo em si. \xc9 essa classe, e n\xe3o o nome do tipo, que protege a\\nintegridade da configura\xe7\xe3o publicada: uma retifica\xe7\xe3o que mudasse a\\nclasse de congelamento no meio de uma cadeia deixaria amb\xedguo se a vers\xe3o\\nvigente da configura\xe7\xe3o \xe9 a que o ato original congelou ou a que a\\nretifica\xe7\xe3o teria congelado.","A compara\xe7\xe3o \xe9 entre a classe do **retificador** e a classe que o **retificado**\\ncongelou no seu pr\xf3prio registro, n\xe3o o que o tipo dele diz hoje: o\\ncat\xe1logo \xe9 edit\xe1vel, e a classe do ato j\xe1 publicado n\xe3o muda\\nretroativamente se o cadastro do tipo mudar depois.","A classe do retificador depende de quem registra. No registro feito direto no\\nPublica\xe7\xf5es, ela \xe9 resolvida agora, do tipo vigente na data deste registro.\\nNo ato que a Sele\xe7\xe3o origina a partir de um item do edital, ela vem da\\nclassifica\xe7\xe3o que a vers\xe3o publicada do edital congelou para o tipo, e chega na\\npr\xf3pria requisi\xe7\xe3o: mudar o tipo no cat\xe1logo depois da publica\xe7\xe3o n\xe3o muda a\\nclasse com que o processo corrige os seus atos (UNI-REQ-0157)."],"comoResolver":["Verifique o tipo de ato usado na retifica\xe7\xe3o: ele precisa ter a mesma\\nclasse de congelamento (`congelaConfiguracao`) que o tipo do ato\\nretificado tinha no instante em que este foi registrado. Um aviso pode\\nretificar outro aviso; um edital que congela configura\xe7\xe3o s\xf3 pode ser\\nretificado por um ato cujo tipo tamb\xe9m congela.","Para ato de **processo seletivo**, o caminho \xe9 a **Sele\xe7\xe3o**: a opera\xe7\xe3o\\nadministrativa de Publica\xe7\xf5es recusa esse v\xednculo, inclusive na retifica\xe7\xe3o, com\\n[`vinculo_exige_registro_pelo_dominio`](/erros/uniplus.publicacoes.ato_normativo.vinculo_exige_registro_pelo_dominio). Publique e retifique pela\\nSele\xe7\xe3o, na p\xe1gina \\"Publica\xe7\xf5es\\" do processo."],"ondeAparece":["Registro de ato normativo, quando o ato declara atoRetificadoId"]},"modulo":{"id":"publicacoes","nome":"Publica\xe7\xf5es","assunto":"Ato normativo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"bac0ecb24f352b6341ba53a00922b6237dd7a678"}}')}}]);